(()=>{const steps=[
["FACE DETECTION","얼굴 영역을 정밀하게 감지하고 있어요","정면 얼굴과 분석 가능한 영역을 확인하고 있어요","SCANNING FACE",18],
["LANDMARK MAPPING","얼굴의 주요 특징점을 연결하고 있어요","눈 · 코 · 입 · 윤곽의 위치 관계를 68개 포인트로 매핑하고 있어요","68 LANDMARKS",36],
["GEOMETRY ANALYSIS","얼굴 비율과 구조를 계산하고 있어요","눈 사이 거리, 윤곽, 중심축 등 시각적 특징을 비교하고 있어요","GEOMETRY MAP",53],
["FEATURE EXTRACTION","얼굴 특징을 벡터로 변환하고 있어요","분석된 특징을 유사도 검색을 위한 표현으로 정리하고 있어요","FEATURE VECTOR",68],
["SIMILARITY SEARCH","데이터셋에서 닮은 후보를 탐색하고 있어요","후보군을 빠르게 비교하며 유사도가 높은 인물을 좁히고 있어요","SEARCHING DATASET",86],
["TOP MATCH SELECTION","가장 닮은 TOP 3를 선별하고 있어요","상위 후보를 다시 비교해 최종 결과를 준비하고 있어요","RANKING MATCHES",97]
],durations=[2100,2300,2200,2300,3300,2300];let timer=null,active=null;
function render(el){if(el.dataset.analysisEnhanced)return;el.dataset.analysisEnhanced="2";active=el;el.innerHTML='<div class="ai-analysis-card"><div class="ai-analysis-head"><span>VISUAL SIMILARITY ENGINE</span><b class="ai-step-count">01 / 06</b></div><div class="ai-scan"><div class="ai-orbit o1"></div><div class="ai-orbit o2"></div><div class="ai-face-grid"><i></i><i></i><i></i><i></i><span class="ai-scan-line"></span><span class="ai-axis"></span><span class="ai-face-mark m1"></span><span class="ai-face-mark m2"></span><span class="ai-face-mark m3"></span><span class="ai-face-mark m4"></span><span class="ai-face-mark m5"></span><span class="ai-face-mark m6"></span><span class="ai-face-mark m7"></span><span class="ai-face-mark m8"></span></div><div class="ai-telemetry"><span>FACE <b>LOCKED</b></span><span>QUALITY <b>HIGH</b></span><span>VECTOR <b class="vector-id">--</b></span></div></div><div class="ai-stage"><small class="ai-code"></small><strong class="ai-title"></strong><p class="ai-desc"></p><div class="ai-candidates"><span></span><span></span><span></span><span></span><span></span><span></span><span></span></div></div><div class="ai-progress"><span></span></div><div class="ai-foot"><span class="ai-status">INITIALIZING</span><span class="ai-percent">0%</span></div></div>';
let index=0,elapsed=0,total=durations.reduce((a,b)=>a+b,0),seed=Math.floor(Math.random()*9000)+1000;const status=["DETECTING","MAPPING","MEASURING","ENCODING","SEARCHING","RANKING"];
function show(){if(!document.body.contains(el)){clearTimeout(timer);return}const s=steps[index],card=el.querySelector(".ai-analysis-card");card.dataset.phase=index+1;el.querySelector(".ai-code").textContent=s[0]+"  ·  "+s[3];el.querySelector(".ai-title").textContent=s[1];el.querySelector(".ai-desc").textContent=s[2];el.querySelector(".ai-step-count").textContent=String(index+1).padStart(2,"0")+" / 06";el.querySelector(".ai-status").textContent=status[index];el.querySelector(".vector-id").textContent=index<3?"--":("#"+(seed+index*137));el.querySelector(".ai-progress span").style.width=s[4]+"%";el.querySelector(".ai-percent").textContent=s[4]+"%";const dots=el.querySelectorAll(".ai-candidates span");dots.forEach((d,n)=>{d.style.opacity=index>=4?String(.25+((n+index)%4)*.22):".12";d.style.transform=index>=4?"scale("+(0.72+((n+index)%3)*.14)+")":"scale(.72)"});timer=setTimeout(()=>{elapsed+=durations[index];if(index<steps.length-1){index++;show()}else{el.querySelector(".ai-progress span").style.width="99%";el.querySelector(".ai-percent").textContent="99%";el.querySelector(".ai-status").textContent="FINALIZING"}},durations[index])}show()}
new MutationObserver(()=>{const el=document.querySelector(".loading-overlay");if(el&&el!==active)render(el);if(!el)active=null}).observe(document.documentElement,{childList:true,subtree:true});})();